        "folate" to RegistryNutrient("g", read = { it.folate }, aggregate = NutritionRecord.FOLATE_TOTAL, max = 100.0),
        "folicAcid" to RegistryNutrient("g", read = { it.folicAcid }, aggregate = NutritionRecord.FOLIC_ACID_TOTAL, max = 100.0),
        "caffeine" to RegistryNutrient("g", read = { it.caffeine }, aggregate = NutritionRecord.CAFFEINE_TOTAL, max = 100.0),
    )

    /** A NutritionRecord with [values] (nutrient id → Mass or Energy); nutrients not listed stay unset. */
    fun nutritionRecord(times: RecordTimes, metadata: Metadata, name: String?, mealType: Int, values: Map<String, Any>) =
        NutritionRecord(
            startTime = times.start,
            startZoneOffset = times.startOffset,
            endTime = times.end,
            endZoneOffset = times.endOffset,
            metadata = metadata,
            name = name,
            mealType = mealType,
            energy = values["energy"] as Energy?,
            energyFromFat = values["energyFromFat"] as Energy?,
            protein = values["protein"] as Mass?,
            totalCarbohydrate = values["carbohydrates"] as Mass?,
            dietaryFiber = values["fiber"] as Mass?,
            sugar = values["sugar"] as Mass?,
            totalFat = values["totalFat"] as Mass?,
            saturatedFat = values["saturatedFat"] as Mass?,
            monounsaturatedFat = values["monounsaturatedFat"] as Mass?,
            polyunsaturatedFat = values["polyunsaturatedFat"] as Mass?,
            unsaturatedFat = values["unsaturatedFat"] as Mass?,
            transFat = values["transFat"] as Mass?,
            cholesterol = values["cholesterol"] as Mass?,
            sodium = values["sodium"] as Mass?,
            potassium = values["potassium"] as Mass?,
            calcium = values["calcium"] as Mass?,
            iron = values["iron"] as Mass?,
            magnesium = values["magnesium"] as Mass?,
            phosphorus = values["phosphorus"] as Mass?,
            zinc = values["zinc"] as Mass?,
            copper = values["copper"] as Mass?,
            manganese = values["manganese"] as Mass?,
            selenium = values["selenium"] as Mass?,
            chromium = values["chromium"] as Mass?,
            molybdenum = values["molybdenum"] as Mass?,
            iodine = values["iodine"] as Mass?,
            chloride = values["chloride"] as Mass?,
            vitaminA = values["vitaminA"] as Mass?,
            vitaminB6 = values["vitaminB6"] as Mass?,
            vitaminB12 = values["vitaminB12"] as Mass?,
            vitaminC = values["vitaminC"] as Mass?,
            vitaminD = values["vitaminD"] as Mass?,
            vitaminE = values["vitaminE"] as Mass?,
            vitaminK = values["vitaminK"] as Mass?,
            thiamin = values["thiamin"] as Mass?,
            riboflavin = values["riboflavin"] as Mass?,
            niacin = values["niacin"] as Mass?,
            pantothenicAcid = values["pantothenicAcid"] as Mass?,
            biotin = values["biotin"] as Mass?,
            folate = values["folate"] as Mass?,
            folicAcid = values["folicAcid"] as Mass?,
            caffeine = values["caffeine"] as Mass?,
        )
}
